/**
 * Build the starter diagram library (docs/07 option 3, docs/18 Phase 3.3).
 *
 *   node scripts/build-diagram-library.js
 *
 * Renders hand-authored SVG diagrams to PNG and writes index.json. These are
 * drawn here rather than generated by a model on purpose: docs/07's argument
 * is that a generated diagram of a cell is frequently *subtly wrong* in ways a
 * student will not catch, and that a vetted library is both cheaper and more
 * accurate. Every diagram below is deliberately simple and schematic — the
 * canvas adds its own labels, so these carry only the essential structure.
 *
 * Fully offline: no provider, no key, no GPU. Add your own by appending to
 * DIAGRAMS and re-running.
 */

const fs = require("fs");
const path = require("path");
const sharp = require("sharp");

const OUT = path.resolve(__dirname, "../amatic-app/diagram-library");
const W = 640;
const H = 480;

const svg = (body, bg = "#ffffff") =>
  `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">
   <rect width="${W}" height="${H}" fill="${bg}"/>
   <g font-family="Segoe UI, Arial, sans-serif" font-size="17" fill="#1b1b1b">${body}</g></svg>`;

const label = (x, y, t, anchor = "middle", size = 17) =>
  `<text x="${x}" y="${y}" text-anchor="${anchor}" font-size="${size}" fill="#1b1b1b">${t}</text>`;

const arrow = (x1, y1, x2, y2, colour = "#2563eb") =>
  `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${colour}" stroke-width="3" marker-end="url(#a)"/>`;

const DEFS = `<defs><marker id="a" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto">
  <path d="M0 0 L10 5 L0 10 z" fill="#2563eb"/></marker></defs>`;

// ---------------------------------------------------------------------------
// The diagrams. Keywords are what a topic or image request must mention.
// ---------------------------------------------------------------------------

