// ---------------------------------------------------------------------------

async function main() {
  fs.mkdirSync(OUT, { recursive: true });
  const index = {};
  for (const d of DIAGRAMS) {
    const file = `${d.slug}.png`;
    const png = await sharp(Buffer.from(d.svg())).png({ compressionLevel: 9 }).toBuffer();
    fs.writeFileSync(path.join(OUT, file), png);
    index[d.slug] = [
      {
        file,
        title: d.title,
        mimeType: "image/png",
        keywords: d.keywords,
        approvedBy: "hand-authored starter set",
        approvedAt: new Date().toISOString().slice(0, 10),
      },
    ];
    console.log(`${d.slug.padEnd(24)} ${String(Math.round(png.length / 1024)).padStart(4)} KB  ${d.keywords.length} keywords`);
  }
  fs.writeFileSync(path.join(OUT, "index.json"), `${JSON.stringify(index, null, 2)}\n`);
  console.log(`\n${DIAGRAMS.length} diagrams -> ${OUT}`);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
